import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { Monitor, Tv, Smartphone, Wifi, WifiOff, Play, RefreshCw, Settings2, ArrowLeft, ArrowRight, ChevronLeft, ChevronRight, Plus, Search, X, Check, Download, ShieldCheck, Maximize2, Volume2, VolumeX, CalendarDays, Clock3, Zap, Layers3, AlertTriangle, CheckCircle2, Power, Pause, Trophy, MapPin, Signal, Radio, RotateCcw, Send, Link2, Eye, MoreHorizontal } from 'lucide-react';
