  const items=(visibleBundle?.items||[]).filter(eligiblePlacement);
  const content=(position:number)=>bundleItem(visibleBundle,items[position]);
  const [clockNow,setClockNow]=useState(new Date());const planningIsSimulated=useRef(false);
  const [page,setPage]=useState(0),[activeSchedule,setActiveSchedule]=useState<Row|null>(null),[planChoice,setPlanChoice]=useState(''),[layout,setLayout]=useState(screen.layout||'full');
  const [sideBundle]=useState<Row|null>(()=>zoneBundle(data,screen,'side')),[bottomBundle]=useState<Row|null>(()=>zoneBundle(data,screen,'bottom'));
  const defaultBundle=useRef<Row|null>(releaseBundle(data,screen.scheduledReturnVersion||screen.desiredVersion||screen.confirmedVersion));
  const playerCanvas=useRef<HTMLDivElement>(null),seenEvent=useRef(''),initialScheduleChecked=useRef(false);
  const leaveFullscreen=()=>{setImmersive(false);if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});};
  const enterFullscreen=()=>{setImmersive(true);const root=experienceRoot.current;if(root?.requestFullscreen)root.requestFullscreen().then(()=>{nativeFullscreen.current=true;}).catch(()=>{});};
  useEffect(()=>{const onChange=()=>{if(nativeFullscreen.current&&!document.fullscreenElement){nativeFullscreen.current=false;setImmersive(false);}};document.addEventListener('fullscreenchange',onChange);return()=>document.removeEventListener('fullscreenchange',onChange);},[]);
  const hours=hoursActive(screen.hours,clockNow),billing=data.settings?.billing;
