  const [partnersOn,setPartnersOn]=useState(true),[sponsorTick,setSponsorTick]=useState(0);
  const campaignSignature=(data.campaigns||[]).map((c:Row)=>`${c.id}:${c.status}:${c.activePlan?.planVersion||c.planVersion||1}`).join('|');
  const sponsorPool=useMemo(()=>{const today=new Date().toISOString().slice(0,10);const entries=(data.campaigns||[]).map((c:Row)=>c.status!=='paused'&&c.activePlan?{...structuredClone(c.activePlan),id:c.id,plays:c.plays,status:'published'}:c).filter((c:Row)=>c.status==='published'&&(!c.start||c.start<=today)&&(!c.end||c.end>=today)&&(!c.orientation||c.orientation==='any'||c.orientation===(portrait?'portrait':'landscape'))&&(!c.targets?.length||c.targets.includes(screen.id))).map((c:Row)=>({...structuredClone(c),partner:structuredClone(c.partner??data.sponsors?.find((sp:Row)=>sp.id===c.sponsorId)??{name:'Clubpartner'}),art:structuredClone(Object.prototype.hasOwnProperty.call(c,'art')?c.art:data.content?.find((it:Row)=>it.id===(c.creativeId||c.creative))||null)}));const pool:Row[]=[];const scores=new Map<string,number>(entries.map((c:Row)=>[c.id,0]));const total=entries.reduce((sum:number,c:Row)=>sum+Math.max(1,Math.min(5,Number(c.weight)||1)),0);for(let slot=0;slot<60&&entries.length;slot++){for(const c of entries)scores.set(c.id,(scores.get(c.id)||0)+Math.max(1,Math.min(5,Number(c.weight)||1)));const previous=pool[pool.length-1]?.id;const blocked=entries.length>1&&previous===pool[pool.length-2]?.id?previous:null;const c=[...entries].filter((c:Row)=>c.id!==blocked).sort((a:Row,b:Row)=>(scores.get(b.id)||0)-(scores.get(a.id)||0))[0];pool.push(c);scores.set(c.id,(scores.get(c.id)||0)-total);}return pool;},[campaignSignature,portrait,screen.id]);
