  const sponsor=sponsorPool[sponsorIndex];const sponsorVisible=Boolean(partnersOn&&sponsor&&hasGood&&!goal&&['play','offline'].includes(stage)&&sponsorTick%10<6);
  const sponsorHold=sponsorVisible&&sponsor?.position==='fullscreen';
  const indexRef=useRef(index);indexRef.current=index;
  const trimLength=Number(activePlacement.trimEnd)>Number(activePlacement.trimStart)?Number(activePlacement.trimEnd)-Number(activePlacement.trimStart):0;const duration=Math.max(1,Math.min(3600,trimLength||Number(activePlacement.duration)||Number(content(index)?.duration)||12));
  const item=content(index);const presentationItem=poster&&item?{...item,type:'dynamic',family:'welcome',settings:{...item.settings,title:'Je clubverhaal blijft in beeld',body:'Stilstaand alternatief voor een tijdelijk niet-afspeelbaar item',mediaUrl:null,mediaKind:'image'}}:item; const minCount=Math.max(1,items.length);
  const profile=screen.platform==='LG webOS'?'LG compatibiliteitsprofiel':screen.platform==='Android'?'Android WebView-profiel':'Web / PWA-profiel';
  const beginSync=()=>{if(offline){toast('Maak de demoverbinding eerst weer online om nieuwe inhoud op te halen.');return;}const bundle=releaseBundle(data,screen.desiredVersion);if(!bundle){toast('Publiceer eerst een playlist voor dit scherm.');setStage('error');return;}setPendingBundle(bundle);setProgress(0);setPending(true);setStage('download');setReceipt('Nieuwe publicatie ontvangen');};
