  useEffect(()=>{if(stage!=='download')return;const t=window.setInterval(()=>setProgress(v=>Math.min(100,v+7+Math.round(Math.random()*7))),230);return()=>clearInterval(t);},[stage]);
  useEffect(()=>{if(stage==='download'&&progress>=100){setStage('verify');setReceipt('Alle bestanden lokaal klaar');}},[progress,stage]);
  useEffect(()=>{if(stage!=='verify')return;const t=window.setTimeout(()=>{setStage('transition');setReceipt('Wacht op overgangsmoment');},1200);return()=>clearTimeout(t);},[stage]);
  useEffect(()=>{if(stage!=='transition'||hasGood)return;const t=window.setTimeout(()=>confirm(),1400);return()=>clearTimeout(t);},[stage,hasGood]);
  useEffect(()=>{if(stage!=='recovery')return;const t=window.setTimeout(()=>{setOffline(false);const bundle=releaseBundle(data,screen.desiredVersion);setPendingBundle(bundle);setPending(Boolean(bundle));setStage(bundle?'download':hasGood?'play':'pairing');setProgress(0);setReceipt('Verbinding hersteld; publicatie wordt opnieuw gecontroleerd · demo');update((d:Row)=>{const s=d.screens?.find((s:Row)=>s.id===screen.id);if(s){s.status='online';s.lastSeen=new Date().toISOString();}});},2200);return()=>clearTimeout(t);},[stage,hasGood]);
  useEffect(()=>{if(!hasGood||paused||goal||sponsorHold||['error','recovery','no-content','offline-empty','billing-lock','billing-check','closed'].includes(stage))return;const t=window.setInterval(()=>setElapsed(v=>v+.1),100);return()=>clearInterval(t);},[hasGood,paused,goal,stage,sponsorHold]);
  useEffect(()=>{if(elapsed<duration)return;setElapsed(0);if(pending&&stage==='transition'){confirm();return;}if(page+1<pageCount(item)){setPage(p=>p+1);return;}setPage(0);setIndex(i=>(i+1)%minCount);},[elapsed,duration,minCount,pending,stage,page]);
