  useEffect(()=>{if(!hasGood||paused||goal||!partnersOn||!['play','offline'].includes(stage))return;const t=window.setInterval(()=>setSponsorTick(v=>v+1),1000);return()=>clearInterval(t);},[hasGood,paused,goal,partnersOn,stage]);
